      "narration": "The trail: Shinjuku. Just Shinjuku.",
      "line": "No longest leg and no driver, so the only traffic was foot traffic in Shinjuku."
    },
    "awards": {
      "narration": "And now, the awards for this Tokyo crew."
    },
    "receipt": {
      "narration": "JPY 86,000 all in, JPY 43,000 each over 12 expenses and 7 meals. Everything settled.",
      "line": "Sign here and dream of the next station."
    },
    "stamp": {
      "narration": "Stamp this one in the passport: Tokyo."
    },
    "postcard": {
      "narration": "The last card, before the lights dim.",
      "line": "Wish you were here, but not too much. Shinjuku sends its neon regards."
    }
  },
